import crypto from 'node:crypto';
import { Resend } from 'resend';

const PAGE_HTML = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>5-Minute Reminder Test</title>
  <style>
    :root{--ink:#14213d;--muted:#5c6b82;--blue:#2563eb;--blue2:#1d4ed8;--good:#087f5b;--bad:#b42318}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:linear-gradient(145deg,#edf4ff 0,#f8fafc 48%,#eefbf6 100%);min-height:100vh}
    .shell{max-width:760px;margin:auto;padding:28px 16px 56px}.nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}
    .brand{display:flex;align-items:center;gap:11px;font-weight:850;font-size:20px}.logo{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:var(--blue);color:white}
    .test{font-size:12px;background:#fef3c7;color:#92400e;padding:6px 10px;border-radius:999px;font-weight:800}.card{background:#fff;border:1px solid #d2ddeb;border-radius:24px;padding:28px;box-shadow:0 24px 70px rgba(30,55,90,.13)}
    h1{font-size:clamp(34px,7vw,48px);line-height:1.06;letter-spacing:-.035em;margin:0 0 12px}.sub{margin:0 0 24px;color:var(--muted);line-height:1.55}
    .notice{background:#eff6ff;border:1px solid #bfdbfe;border-radius:14px;padding:14px 16px;margin-bottom:22px;color:#1e40af;line-height:1.5;font-size:14px}
    .grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.full{grid-column:1/-1}label{display:block;font-weight:750;font-size:14px;margin-bottom:7px}
    input,textarea{width:100%;font:inherit;color:var(--ink);background:#fff;border:1px solid #cfd9e7;border-radius:12px;padding:12px 13px;outline:none}textarea{min-height:110px;resize:vertical}
    button{width:100%;border:0;border-radius:13px;padding:15px 18px;background:var(--blue);color:#fff;font:inherit;font-weight:850;cursor:pointer}button:hover{background:var(--blue2)}button:disabled{opacity:.6}
    .status{display:none;margin-top:15px;padding:13px 15px;border-radius:12px;font-size:14px;line-height:1.5}.status.good{display:block;background:#ecfdf3;color:var(--good);border:1px solid #abefc6}.status.bad{display:block;background:#fef3f2;color:var(--bad);border:1px solid #fecdca}
    .small{font-size:12px;color:var(--muted);line-height:1.55;margin:15px 0 0;text-align:center}.trap{position:absolute;left:-9999px;opacity:0;height:0}.back{display:inline-block;margin-top:22px;color:var(--blue);text-decoration:none;font-weight:700}
    @media(max-width:560px){.shell{padding:20px 14px 40px}.card{padding:22px;border-radius:18px}.grid{grid-template-columns:1fr}.full{grid-column:auto}}
  </style>
</head>
<body>
  <main class="shell">
    <nav class="nav"><div class="brand"><span class="logo">5</span> Reminder Test</div><span class="test">TEMPORARY TEST</span></nav>
    <form class="card" id="testForm" novalidate>
      <h1>Test a reminder in 5 minutes</h1>
      <p class="sub">We will email you a confirmation first. After you tap the confirmation button, the test reminder will be scheduled for five minutes later.</p>
      <div class="notice"><strong>How to test:</strong> submit this form, open the confirmation email, tap <strong>Confirm 5-minute test</strong>, then wait about five minutes.</div>
      <div class="grid">
        <div><label for="name">Your name</label><input id="name" autocomplete="name" maxlength="80" required placeholder="David"></div>
        <div><label for="email">Email address</label><input id="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></div>
        <div class="full"><label for="title">Reminder title</label><input id="title" maxlength="120" required value="5-minute reminder test"></div>
        <div class="full"><label for="message">Reminder details</label><textarea id="message" maxlength="1500" required placeholder="This is my five-minute test reminder."></textarea></div>
        <div class="trap"><label for="website">Website</label><input id="website" tabindex="-1" autocomplete="off"></div>
        <div class="full"><button id="submitButton" type="submit">Send confirmation email</button><div id="status" class="status"></div><p class="small">This temporary page is only for testing scheduled email delivery.</p></div>
      </div>
      <a class="back" href="/">← Return to regular reminders</a>
    </form>
  </main>
  <script>
    const form=document.getElementById('testForm');const button=document.getElementById('submitButton');const statusBox=document.getElementById('status');
    form.addEventListener('submit',async function(event){event.preventDefault();statusBox.className='status';statusBox.textContent='';if(!form.reportValidity())return;button.disabled=true;button.textContent='Sending confirmation…';try{const response=await fetch('/test-5-min',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recipient_name:document.getElementById('name').value,recipient_email:document.getElementById('email').value,reminder_title:document.getElementById('title').value,reminder_message:document.getElementById('message').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',website:document.getElementById('website').value})});const data=await response.json().catch(function(){return{}});if(!response.ok)throw new Error(data.error||'Unable to create the test.');statusBox.className='status good';statusBox.textContent=data.message}catch(error){statusBox.className='status bad';statusBox.textContent=error.message||'Something went wrong.'}finally{button.disabled=false;button.textContent='Send confirmation email'}});
  </script>
</body>
</html>`;

function requireEnv(name){const value=String(process.env[name]||'').trim();if(!value)throw new Error('Missing environment variable: '+name);return value}
function sendJson(res,status,body){res.status(status);res.setHeader('Content-Type','application/json; charset=utf-8');res.setHeader('Cache-Control','no-store');return res.end(JSON.stringify(body))}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,function(char){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[char]})}
function sendHtml(res,status,title,message){res.status(status);res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Cache-Control','no-store');return res.end('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escapeHtml(title)+'</title><style>body{margin:0;background:#f4f7fb;font-family:Arial,sans-serif;color:#172033;display:grid;min-height:100vh;place-items:center;padding:24px;box-sizing:border-box}.card{max-width:620px;background:#fff;border:1px solid #dce4ef;border-radius:22px;padding:34px;box-shadow:0 18px 50px rgba(30,55,90,.12);text-align:center}h1{margin:0 0 14px;font-size:30px}p{font-size:17px;line-height:1.6;color:#526078}a{color:#2563eb}</style></head><body><div class="card"><h1>'+escapeHtml(title)+'</h1><p>'+escapeHtml(message)+'</p><p><a href="/test-5-min">Create another 5-minute test</a></p></div></body></html>')}
function getResend(){return new Resend(requireEnv('RESEND_API_KEY'))}
function supabaseConfig(){return{url:requireEnv('SUPABASE_URL').replace(/\/+$/,''),key:requireEnv('SUPABASE_SECRET_KEY')}}
async function supabaseRequest(path,options={}){const{url,key}=supabaseConfig();const headers={apikey:key,Accept:'application/json',...options.headers};if(options.body!==undefined&&!headers['Content-Type'])headers['Content-Type']='application/json';const response=await fetch(url+'/rest/v1/'+path,{method:options.method||'GET',headers,body:options.body===undefined?undefined:JSON.stringify(options.body),cache:'no-store'});const text=await response.text();let data=null;if(text){try{data=JSON.parse(text)}catch{data=text}}if(!response.ok){const message=typeof data==='object'&&data?(data.message||data.error||data.hint||JSON.stringify(data)):String(data||response.statusText);const error=new Error(message||'Supabase request failed.');error.status=response.status;error.details=data;throw error}return{data,response}}
function queryString(params){const search=new URLSearchParams();for(const[key,value]of Object.entries(params)){if(value!==undefined&&value!==null)search.set(key,String(value))}return search.toString()}
function safeEmail(value){const email=String(value||'').trim().toLowerCase();if(email.length>254)return'';return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)?email:''}
function validTimezone(zone){if(!zone||zone.length>100)return false;try{Intl.DateTimeFormat('en-US',{timeZone:zone}).format();return true}catch{return false}}
function makeNumericId(){return Date.now()*1000+crypto.randomInt(0,1000)}
function makeManageToken(id){const idText=String(id);const signature=crypto.createHmac('sha256',requireEnv('TOKEN_SECRET')).update(idText).digest('base64url');return idText+'.'+signature}
function readManageToken(token){const parts=String(token||'').split('.');if(parts.length!==2||!/^\d+$/.test(parts[0]))return null;const expected=crypto.createHmac('sha256',requireEnv('TOKEN_SECRET')).update(parts[0]).digest('base64url');const a=Buffer.from(parts[1]);const b=Buffer.from(expected);if(a.length!==b.length||!crypto.timingSafeEqual(a,b))return null;return parts[0]}
function getIpHash(req){const forwarded=String(req.headers['x-forwarded-for']||'').split(',')[0].trim();const ip=forwarded||String(req.socket?.remoteAddress||'unknown');return crypto.createHmac('sha256',requireEnv('RATE_LIMIT_SALT')).update(ip).digest('hex')}
function getBaseUrl(req){const configured=String(process.env.APP_URL||'').trim().replace(/\/+$/,'');if(configured)return configured;const protocol=String(req.headers['x-forwarded-proto']||'https').split(',')[0].trim();return protocol+'://'+String(req.headers.host||'')}
async function countRecentBy(column,value,since){const query=queryString({select:'id',[column]:'eq.'+value,created_at:'gte.'+since,limit:5});const{data}=await supabaseRequest('reminders?'+query);return Array.isArray(data)?data.length:0}
async function insertReminder(row){await supabaseRequest('reminders',{method:'POST',headers:{Prefer:'return=minimal'},body:row})}
async function selectReminderById(id){const query=queryString({select:'*',id:'eq.'+id,limit:1});const{data}=await supabaseRequest('reminders?'+query);return Array.isArray(data)&&data.length?data[0]:null}
async function updateReminderById(id,changes){const query=queryString({id:'eq.'+id});await supabaseRequest('reminders?'+query,{method:'PATCH',headers:{Prefer:'return=minimal'},body:changes})}
async function deleteReminderById(id){const query=queryString({id:'eq.'+id});await supabaseRequest('reminders?'+query,{method:'DELETE',headers:{Prefer:'return=minimal'}})}

async function createTest(req,res){let reminderId=null;let stage='start';try{const body=typeof req.body==='string'?JSON.parse(req.body):(req.body||{});if(String(body.website||'').trim())return sendJson(res,200,{ok:true,message:'Please check your email.'});const recipientName=String(body.recipient_name||'').trim();const recipientEmail=safeEmail(body.recipient_email);const reminderTitle=String(body.reminder_title||'').trim();const reminderMessage=String(body.reminder_message||'').trim();const timezone=String(body.timezone||'UTC').trim();if(!recipientName||recipientName.length>80)return sendJson(res,400,{error:'Enter a valid name.'});if(!recipientEmail)return sendJson(res,400,{error:'Enter a valid email address.'});if(!reminderTitle||reminderTitle.length>120)return sendJson(res,400,{error:'Enter a title of 120 characters or fewer.'});if(!reminderMessage||reminderMessage.length>1500)return sendJson(res,400,{error:'Enter reminder details.'});if(!validTimezone(timezone))return sendJson(res,400,{error:'Your time zone could not be detected.'});const now=new Date();const since=new Date(now.getTime()-86400000).toISOString();const ipHash=getIpHash(req);const ipCount=await countRecentBy('created_ip_hash',ipHash,since);const emailCount=await countRecentBy('recipient_email',recipientEmail,since);if(ipCount>=5||emailCount>=5)return sendJson(res,429,{error:'Too many tests today. Please try again tomorrow.'});stage='insert';reminderId=makeNumericId();await insertReminder({id:reminderId,created_at:now.toISOString(),recipient_name:recipientName,recipient_email:recipientEmail,reminder_title:reminderTitle,reminder_message:reminderMessage,event_at:new Date(now.getTime()+600000).toISOString(),timezone,remind_one_month:false,remind_one_week:false,remind_one_day:false,status:'pending_verification',created_ip_hash:ipHash});stage='email';const token=makeManageToken(reminderId);const confirmUrl=getBaseUrl(req)+'/test-5-min?confirm='+encodeURIComponent(token);const cancelUrl=getBaseUrl(req)+'/api/cancel-reminder?token='+encodeURIComponent(token);const{data,error}=await getResend().emails.send({from:requireEnv('EMAIL_FROM'),to:[recipientEmail],subject:'Confirm your 5-minute reminder test',html:'<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#172033;line-height:1.6"><h1>Confirm your 5-minute test</h1><p>Hello '+escapeHtml(recipientName)+',</p><p>Tap the button below. Your test reminder will be scheduled for approximately five minutes later.</p><div style="background:#f4f7fb;border:1px solid #dce4ef;border-radius:14px;padding:18px"><strong>'+escapeHtml(reminderTitle)+'</strong><br><span style="color:#526078">'+escapeHtml(reminderMessage)+'</span></div><p><a href="'+confirmUrl+'" style="display:inline-block;background:#2563eb;color:white;text-decoration:none;padding:13px 20px;border-radius:10px;font-weight:bold">Confirm 5-minute test</a></p><p style="font-size:13px;color:#6b7280">If you did not request this, you may ignore this email or <a href="'+cancelUrl+'">cancel it</a>.</p></div>'},{idempotencyKey:'five-minute-test-confirm/'+reminderId});if(error)throw error;if(!data?.id)throw new Error('Resend returned no email ID.');return sendJson(res,201,{ok:true,message:'Check your email and tap “Confirm 5-minute test.”'})}catch(error){console.error('five-minute test create error',{stage,reminderId,message:error?.message||String(error)});if(reminderId&&stage==='email'){try{await deleteReminderById(reminderId)}catch{}}return sendJson(res,500,{error:'We could not create the five-minute test. Please try again.'})}}

async function confirmTest(req,res,token){try{const id=readManageToken(token);if(!id)return sendHtml(res,400,'Invalid link','This confirmation link is invalid.');const row=await selectReminderById(id);if(!row)return sendHtml(res,404,'Test not found','This test no longer exists.');if(row.status==='cancelled')return sendHtml(res,200,'Test cancelled','This test has already been cancelled.');if(row.status==='active')return sendHtml(res,200,'Already scheduled','Your test reminder is already scheduled. Please wait for the email.');const createdAt=new Date(row.created_at).getTime();if(!Number.isFinite(createdAt)||createdAt+172800000<Date.now()){await updateReminderById(id,{status:'expired'});return sendHtml(res,410,'Confirmation expired','This test confirmation link has expired.')}const scheduledAt=new Date(Date.now()+300000).toISOString();const{data,error}=await getResend().emails.send({from:requireEnv('EMAIL_FROM'),to:[row.recipient_email],subject:'5-minute test reminder: '+row.reminder_title,html:'<div style="font-family:Arial,sans-serif;max-width:640px;margin:auto;color:#172033;line-height:1.6"><p>Hello '+escapeHtml(row.recipient_name)+',</p><h1>'+escapeHtml(row.reminder_title)+'</h1><p style="font-weight:bold;color:#2563eb">Your 5-minute reminder test worked.</p><div style="background:#f4f7fb;border:1px solid #dce4ef;border-radius:14px;padding:18px"><span style="color:#526078">'+escapeHtml(row.reminder_message)+'</span></div></div>',scheduledAt},{idempotencyKey:'five-minute-test-reminder/'+id});if(error)throw error;if(!data?.id)throw new Error('Resend returned no scheduled email ID.');await updateReminderById(id,{status:'active',verified_at:new Date().toISOString(),one_day_sent_at:scheduledAt});return sendHtml(res,200,'5-minute test scheduled','Your confirmation worked. Keep checking your email; the test reminder is scheduled for about five minutes from now.')}catch(error){console.error('five-minute test confirm error',error);return sendHtml(res,500,'Something went wrong','We could not schedule the test reminder. Please try again.')}}

export default async function handler(req,res){const url=new URL(req.url||'/test-5-min','https://'+(req.headers.host||'localhost'));if(req.method==='GET'&&url.searchParams.get('confirm'))return confirmTest(req,res,url.searchParams.get('confirm'));if(req.method==='GET'){res.status(200);res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Cache-Control','public, max-age=0, must-revalidate');return res.end(PAGE_HTML)}if(req.method==='POST')return createTest(req,res);res.setHeader('Allow','GET, POST');return sendJson(res,405,{error:'Method not allowed.'})}
